import fs from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';

// All paths, palettes and characters below are original artwork for 小小故事屋.
// SVG is the editable master. PNG files are the bundled, offline story assets.
const ROOT = process.cwd();
const OUT = path.join(ROOT, 'assets/stories');
const CACHE = path.join(ROOT, '.cache/illustrations');
const stories = JSON.parse(await fs.readFile(path.join(ROOT, 'src/content/stories.json'), 'utf8'));
const only = process.argv.find(a => a.startsWith('--story='))?.split('=')[1];
const sample = process.argv.includes('--sample');
const escape = x => String(x).replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
const C = { cream:'#FFF2D8', ink:'#263D48', blue:'#97C4C6', ochre:'#DEB456', moss:'#779382', coral:'#D98C72' };
const E = (cx,cy,rx,ry,fill,extra='') => `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${fill}" ${extra}/>`;
const R = (x,y,w,h,fill,r=10,extra='') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}" ${extra}/>`;
const P = (d,fill,stroke='',sw=3,extra='') => `<path d="${d}" fill="${fill}" ${stroke?`stroke="${stroke}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"`:''} ${extra}/>`;
const G = (x,y,s,art,rot=0) => `<g transform="translate(${x} ${y}) rotate(${rot}) scale(${s})">${art}</g>`;
const line = (x1,y1,x2,y2,c,sw=2,extra='') => `<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="${c}" stroke-width="${sw}" stroke-linecap="round" ${extra}/>`;
const rng = (seed) => {let a=seed;return () => {a=(a*1664525+1013904223)>>>0;return a/4294967296;};};
const star = (x,y,s,c='#F9DFA4') => G(x,y,s,P('M0 -10 Q2 -2 9 0 Q2 2 0 11 Q-2 2 -9 0 Q-2 -2 0 -10',c));
function stars(seed=1,n=38){const rand=rng(seed);return Array.from({length:n},()=>star(40+rand()*920,40+rand()*420,.25+rand()*.55,'#F7D8A2')).join('');}
const glow = (x,y,r=60) => E(x,y,r,r,'url(#glow)');
const moon = (x,y,r=58,full=false) => `${E(x,y,r*2,r*2,'url(#moonHalo)')}${E(x,y,r,r,'#FFEBC2')}${full?'':E(x+r*.4,y-r*.27,r*.8,r*.86,'#274958')}${full?E(x-r*.2,y+r*.1,r*.24,r*.25,'#F3DDB5','opacity=".35"'):''}`;
function leaf(x,y,s,color='#85A58A',rot=0){return G(x,y,s,`${P('M0 0 C-55 -15 -61 -70 0 -100 C55 -60 52 -15 0 0',color)}${P('M0 -4 Q-8 -43 0 -83','none','#D8D9AF',2,'opacity=".5"')}`,rot);}
function grass(x,y,s=1,c='#758E77'){return G(x,y,s,P('M-18 0 Q-22 -33 -36 -43 Q-12 -40 -8 0 M-3 0 Q-10 -42 3 -62 Q12 -40 6 0 M12 0 Q22 -33 38 -35 Q23 -15 20 0',c));}
function flower(x,y,s=1,c='#F5DBAB'){return G(x,y,s,`${line(0,0,0,-30,'#627E64',3)}${E(-7,-17,9,4,'#78907A')}${[-1,1].map(k=>E(k*8,-38,9,11,c)).join('')}${E(0,-46,9,11,c)}${E(0,-32,9,11,c)}${E(0,-39,5,5,'#C89451')}`);}
function meadow(y=670,c='#344F51',seed=1){const rand=rng(seed);let a=P(`M-20 ${y+25} Q130 ${y-85} 320 ${y-18} Q550 ${y-75} 770 ${y-10} Q900 ${y-46} 1020 ${y+8} L1020 820 L-20 820Z`,c);for(let i=0;i<28;i++){const x=rand()*1050,yy=y+40+rand()*105;a+=grass(x,yy,.4+rand()*.5,i%3?'#6F8979':'#9CA787');if(i%3===0)a+=flower(x+20,yy,.35+rand()*.3);}return a;}
function evergreen(x,y,s=1,c='#385F59'){return G(x,y,s,`${R(-7,-180,14,215,'#626B58',4)}${P('M0 -410 C-14 -350 -54 -320 -82 -297 L-45 -296 C-70 -250 -105 -226 -133 -215 L-82 -210 C-118 -159 -149 -136 -179 -120 Q0 -70 179 -120 C149 -139 110 -168 78 -210 L132 -215 C100 -238 64 -267 44 -297 L82 -297 C39 -331 16 -365 0 -410','#0000')}${P('M0 -410 C-14 -350 -54 -320 -82 -297 L-45 -296 C-70 -250 -105 -226 -133 -215 L-82 -210 C-118 -159 -149 -136 -179 -120 Q0 -70 179 -120 C149 -139 110 -168 78 -210 L132 -215 C100 -238 64 -267 44 -297 L82 -297 C39 -331 16 -365 0 -410',c)}${P('M0 -371 L0 -117 M0 -260 L-54 -234 M0 -214 L58 -183 M0 -163 L-90 -138','none','#98A285',3,'opacity=".22"')}`);}
function tree(x,y,s=1,c='#587C68'){return G(x,y,s,`${P('M-17 0 Q-6 -170 -30 -300 L8 -300 Q-4 -190 24 0Z','#796E55')}${P('M0 -150 Q-75 -218 -88 -270 M3 -210 Q58 -278 68 -320','none','#796E55',15)}${E(-70,-310,110,115,c)}${E(48,-350,123,133,c)}${E(123,-271,100,108,c)}${E(-14,-260,122,99,c)}${Array.from({length:20},(_,i)=>{const ra=rng(i*43+12);return leaf(-120+ra()*240,-220-ra()*155,.18,'#B0BD8E',ra()*150-75);}).join('')}`);}
function mushroom(x,y,s=1){return G(x,y,s,`${R(-7,-27,14,27,'#F5DEB5',5)}${P('M-31 -25 Q-30 -67 0 -67 Q30 -67 31 -25 Q0 -14 -31 -25','#CB8268')}${E(-12,-40,5,5,'#F4DAB7')}${E(10,-52,4,4,'#F4DAB7')}${E(19,-34,4,4,'#F4DAB7')}`);}
function hills(night=true){return `${P('M0 425 Q180 300 370 420 Q570 260 780 410 Q910 350 1000 390 L1000 800 L0 800Z',night?'#365C60':'#9DB6A2')}${P('M0 530 Q240 375 470 525 Q700 400 1000 490 L1000 800 L0 800Z',night?'#476B66':'#B3C7A0')}`;}
function cloud(x,y,s=1,c='#E5DFCB'){return G(x,y,s,P('M-116 32 C-165 29 -154 -31 -108 -34 C-103 -97 -19 -118 16 -71 C65 -111 128 -63 125 -23 C183 -7 160 44 116 44 L-108 44Z',c));}
function envelope(x,y,s=1,rot=0){return G(x,y,s,`${R(-53,-34,106,68,'#F5F0DA',6,'stroke="#BBCBD0" stroke-width="2"')}${P('M-50 -30 L0 8 L50 -30 M-50 30 L-13 1 M50 30 L13 1','none','#B7C9CA',2)}${E(0,7,7,7,'#DCAA6D')}`,rot);}
function lotus(x,y,s=1,lit=false){return G(x,y,s,`${lit?glow(0,-24,100):''}${P('M-103 -10 C-98 -55 -42 -56 -9 -31 C7 -71 82 -59 107 -20 C96 25 24 36 -4 18 C-57 32 -89 15 -103 -10','#8BA98E','#AEC5A3',2)}${P('M-85 -8 L-2 12 L82 -23 M-1 9 L-45 -32 M-1 8 L23 -38','none','#C4D2A6',2)}${lit?`${E(0,-20,42,11,'#FFF0B9')}${star(-14,-36,.9)}${star(24,-28,.5)}`:''}`);}
function fly(x,y,s=1){return `${glow(x,y,25*s)}${G(x,y,s,`${E(-6,-7,6,9,'#BDD4C1','opacity=".75"')}${E(6,-7,6,9,'#BDD4C1','opacity=".75"')}${E(0,0,5,7,'#F6D985')}${E(0,-8,3,3,'#657B69')}`)}`;}
function fireflies(points){return points.map(([x,y,s])=>fly(x,y,s??1)).join('');}
function rabbit(x,y,s=1,pose='hold',flip=false){return G(x,y,s,`<g transform="scale(${flip?-1:1} 1)">${E(0,-7,107,16,'#1C3E3B','opacity=".13"')}${E(64,-112,34,32,'#E7DCC3')}${P('M-49 -261 C-89 -242 -99 -118 -76 -51 Q-5 -12 68 -50 C94 -145 64 -230 34 -260Z','#F5E8CE')}${E(-48,-27,43,24,'#F5E8CE')}${E(45,-27,43,24,'#F5E8CE')}${P('M-58 -305 C-102 -367 -111 -445 -77 -456 C-45 -468 -33 -382 -25 -333Z','#FFF2D8')}${P('M8 -335 C-2 -407 14 -476 44 -466 C77 -453 52 -370 44 -318Z','#FFF2D8')}${P('M-61 -342 Q-90 -422 -76 -434 Q-62 -434 -46 -353Z','#DEB3A5')}${P('M23 -350 Q20 -432 39 -445 Q51 -432 37 -353Z','#DEB3A5')}${E(-7,-294,88,77,'#FFF2D8')}${E(-45,-284,18,11,'#EBAF9B','opacity=".48"')}${E(49,-284,18,11,'#EBAF9B','opacity=".48"')}${E(-36,-305,6,8,C.ink)}${E(29,-305,6,8,C.ink)}${E(-34,-308,2,2,'#FFFAED')}${E(31,-308,2,2,'#FFFAED')}${P('M-12 -286 Q-5 -293 2 -286 Q-5 -275 -12 -286','#C68174')}${P('M-5 -280 Q-5 -265 -18 -270 M-5 -280 Q-4 -266 9 -271','none','#786E63',2)}${P('M-73 -247 Q-9 -216 61 -245 L61 -222 Q-6 -194 -73 -222Z','#A9CDD0')}${P('M37 -226 Q68 -212 79 -180 L50 -169 L24 -219Z','#92BBC1')}${line(61,-184,76,-190,'#DDE7D3',3)}${P('M-72 -223 L59 -83','none','#C99E56',15)}${G(49,-107,1,`${R(-31,-27,85,75,'#D6AD54',12)}${P('M-31 -23 L54 -23 L46 13 Q8 34 -31 6Z','#E4BF6B')}${R(9,3,9,15,'#B58A46',3)}`)}${pose==='wave'?P('M-62 -206 Q-130 -210 -133 -286 Q-129 -306 -111 -297 Q-91 -264 -57 -257Z','#F5E8CE'):P('M-64 -213 Q-113 -193 -87 -145 Q-59 -124 -30 -171 L-18 -191Z','#F5E8CE')}${pose==='hold'||pose==='letter'?P('M57 -208 Q96 -196 75 -155 Q37 -141 7 -169 Q-4 -187 19 -197Z','#F5E8CE'):P('M52 -210 Q100 -174 73 -126 Q61 -113 45 -131 L32 -179Z','#F5E8CE')}${pose==='letter'?envelope(-3,-178,.65,-9):''}</g>`);}
function rabbitSide(x,y,s=1,pose='sit') {return G(x,y,s,`${E(0,-4,118,17,'#173E3B','opacity=".16"')}${E(-55,-57,34,34,'#E9DDC4')}${P('M-40 -209 C-85 -167 -91 -72 -56 -28 Q-6 -6 72 -31 Q106 -72 58 -126 L45 -205Z','#F5E8CE')}${E(55,-24,66,24,'#F5E8CE')}${P('M-50 -225 C-105 -286 -106 -378 -75 -383 Q-45 -383 -24 -249Z','#FFF2D8')}${P('M-1 -248 C-30 -338 -8 -393 17 -388 Q44 -377 29 -251Z','#FFF2D8')}${P('M-61 -260 Q-91 -339 -73 -359 Q-57 -344 -45 -267Z','#DDB3A5')}${P('M6 -269 Q-12 -351 13 -366 Q25 -349 21 -272Z','#DDB3A5')}${E(11,-214,86,69,'#FFF2D8')}${E(73,-195,34,25,'#FFF2D8')}${E(46,-228,6,8,C.ink)}${E(48,-231,2,2,'#FFFAED')}${E(38,-203,20,11,'#EBAF9B','opacity=".5"')}${P('M97 -204 Q110 -206 106 -197 Q101 -189 96 -197Z','#C68174')}${P('M98 -191 Q93 -178 82 -183','none','#786E63',2)}${P('M-47 -162 Q1 -139 58 -165 L64 -140 Q3 -118 -50 -141Z','#A9CDD0')}${P('M-41 -147 L56 -53','none','#C49C54',12)}${R(-42,-81,78,57,'#D8AF59',10)}${P('M-42 -78 L35 -78 Q26 -44 -42 -58Z','#E8C371')}${pose==='offer'?P('M27 -137 Q75 -151 130 -123 Q144 -107 124 -98 Q76 -102 33 -105Z','#F5E8CE'):P('M24 -138 Q62 -153 94 -131 Q112 -111 93 -102 Q51 -105 21 -108Z','#F5E8CE')}${P('M-35 -127 Q-10 -146 20 -112 Q34 -95 20 -84 Q-20 -87 -35 -127Z','#F5E8CE')}`);}
function snail(x,y,s=1,faceRight=false){return G(x,y,s,`<g transform="scale(${faceRight?-1:1} 1)">${E(7,-2,87,12,'#25493E','opacity=".14"')}${P('M-78 -4 Q-98 -20 -76 -45 Q-63 -65 -62 -87 Q-50 -111 -35 -83 L-23 -38 Q35 -20 83 -11 Q71 6 -8 4Z','#E6C4A0')}${E(21,-56,61,61,'#D98B70')}${P('M56 -36 C74 -86 15 -119 -12 -81 C-37 -44 19 -12 34 -47 C45 -72 11 -88 4 -64 C0 -52 14 -43 22 -53','none','#B56955',6)}${P('M-61 -86 L-73 -108 M-39 -86 L-31 -111','none','#D5AC84',6)}${E(-74,-111,5,6,C.ink)}${E(-30,-114,5,6,C.ink)}${P('M-57 -70 Q-47 -63 -39 -72','none','#916C58',2)}${E(-61,-75,6,3,'#D69D7E')}</g>`);}
function pumpkin(x,y,s=1,lit=true){return G(x,y,s,`${P('M-20 -267 Q-30 -332 19 -337 Q42 -331 22 -315 L8 -273','#788C62')}${P('M17 -313 Q80 -352 81 -306 Q75 -280 45 -292','none','#91A06B',6)}${E(0,-137,169,147,'#C18E62')}${E(-79,-139,85,142,'#C69A66')}${E(77,-139,85,142,'#CC9D68')}${E(0,-139,85,147,'#DAAD72')}${P('M-51 3 L-51 -86 Q-51 -130 -12 -130 Q26 -129 26 -85 L26 3Z','#6D7560','#B18758',7)}${R(-42,-79,60,80,'#646E59',7)}${line(-25,-107,-25,-2,'#899173',3)}${E(10,-49,5,5,'#D4BC7C')}${E(84,-153,36,38,'#937651')}${E(84,-153,29,31,lit?'#F8D99C':'#465D58')}${line(55,-153,113,-153,'#B8925D',5)}${line(84,-184,84,-122,'#B8925D',5)}${lit?E(84,-153,78,78,'url(#windowGlow)'):''}${P('M-130 -12 Q-142 -39 -161 -39 Q-155 -10 -130 -12','#8F9A6D')}${P('M136 -8 Q169 -45 180 -20 Q163 -2 136 -8','#8F9A6D')}${E(-10,10,65,9,'#B59C71')}`);}
function box(x,y,s=1){return G(x,y,s,`${R(-38,-52,76,52,'#AF9473',2)}${P('M-38 -52 L-50 -67 L22 -67 L38 -52Z','#C8B08C')}${line(-8,-51,-8,0,'#DBC6A1',13)}${leaf(20,-58,.3,'#769174',52)}`);}
function pond(y=615){return `${E(490,y,375,114,'#A1BCAD')}${E(490,y-4,356,105,'#557D80')}${E(470,y-14,315,78,'#466E78')}${P(`M263 ${y-43} Q470 ${y-70} 661 ${y-38} M244 ${y+10} Q490 ${y-10} 752 ${y+11} M341 ${y+57} Q500 ${y+39} 671 ${y+59}`,'none','#B5C8B1',3,'opacity=".5"')}`;}
function table(x,y,s=1){return G(x,y,s,`${R(-101,-11,18,144,'#8D745C',5)}${R(83,-11,18,144,'#8D745C',5)}${E(0,0,164,47,'#9B8264')}${E(0,-12,164,47,'#C7AA7D')}${E(0,-16,141,32,'#D7BF95')}`);}
function pear(x,y,s=1){return G(x,y,s,`${P('M0 -47 C-20 -45 -13 -27 -29 -15 C-56 14 -23 40 8 28 C41 15 18 -9 9 -24 Q8 -42 0 -47','#D2C97A')}${P('M0 -42 Q1 -56 11 -60','none','#80785B',4)}${leaf(8,-49,.22,'#8EA17A',60)}`);}
