 if(i===4||i===5){a+=moon(300,164,54)+cloud(326,152,.87,'#6A838B')+P('M260 800 Q410 652 702 552 L744 604 Q514 715 465 800Z','#A3A786')+pumpkin(i===4?748:710,650,i===4?1.12:1.35,i===5)+meadow(730,'#365A50',23)+box(i===4?877:894,672,.75)+(i===4?rabbit(328,740,.94,'hold'):rabbitSide(343,747,1.07,'offer'))+lotus(i===4?366:485,i===4?565:610,.84,i===5)+fireflies([[418,504,1],[458,560,.9],[516,584,1.1],[586,534,.8],[658,487,.8]]);
 if(i===5)a+=snail(615,700,.95)+glow(500,584,140); else a+=flower(596,728,.8)+flower(552,768,.7)+flower(624,755,.7);}
