function otherScene(story,index,cover=false){if(story.id==='seed-light')return seedScene(index,cover);if(story.id==='cloud-whale')return whaleScene(index,cover);if(story.id==='fox-library')return foxScene(index,cover);if(story.id==='clock-forest')return clockScene(index,cover);if(story.id==='wind-map')return windScene(index,cover);throw new Error(`No illustration direction for ${story.id}`);}

function svg(art,description,cover=false){return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="${cover?1000:800}" viewBox="${cover?'100 0 800 800':'0 0 1000 800'}"><title>${escape(description)}</title><defs><linearGradient id="night" x2="0" y2="1"><stop stop-color="#244755"/><stop offset="1" stop-color="#64857A"/></linearGradient><linearGradient id="day" x2="0" y2="1"><stop stop-color="#C5D8D1"/><stop offset="1" stop-color="#EEE6C9"/></linearGradient><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#85B6C4"/><stop offset="1" stop-color="#EEE1BC"/></linearGradient><radialGradient id="glow"><stop stop-color="#FFEAB1" stop-opacity=".55"/><stop offset=".3" stop-color="#FFEAB1" stop-opacity=".18"/><stop offset="1" stop-color="#FFEAB1" stop-opacity="0"/></radialGradient><radialGradient id="moonHalo"><stop stop-color="#FFF0BB" stop-opacity=".18"/><stop offset="1" stop-color="#FFF0BB" stop-opacity="0"/></radialGradient><radialGradient id="windowGlow"><stop stop-color="#FCE8A3" stop-opacity=".2"/><stop offset="1" stop-color="#FCE8A3" stop-opacity="0"/></radialGradient><filter id="paper"><feTurbulence type="fractalNoise" baseFrequency=".52" numOctaves="3" seed="8" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".12"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter></defs><g>${art}</g><rect x="0" y="0" width="1000" height="800" fill="#CDBB96" opacity=".2" filter="url(#paper)" style="mix-blend-mode:multiply"/></svg>`;}

await fs.mkdir(CACHE,{recursive:true});
const expectedPages={'moon-post':8,'seed-light':8,'cloud-whale':12,'fox-library':12,'clock-forest':16,'wind-map':16};
for(const story of stories.filter(s=>!only||s.id===only)){
 if(story.pages.length!==expectedPages[story.id])throw new Error(`Storyboard changed for ${story.id}; update the illustration scenes before rendering.`);
 const dir=path.join(OUT,story.id);await fs.mkdir(dir,{recursive:true});
 const scene=(index,cover=false)=>story.id==='moon-post'?moonScene(index,cover):otherScene(story,index,cover);
 const pages=sample?story.pages.slice(0,1):story.pages;
 for(let i=0;i<pages.length;i++){
  const p=pages[i], name=`page-${String(i+1).padStart(2,'0')}`;
  const source=svg(scene(i),`${story.title} · ${p.scene?.setting||''} · ${p.scene?.action||p.text}`);
  await fs.writeFile(path.join(CACHE,`${story.id}-${name}.svg`),source);
  await sharp(Buffer.from(source)).png({compressionLevel:9,palette:false}).toFile(path.join(dir,`${name}.png`));
 }
 const coverSource=svg(scene(0,true),`${story.title} · 原创绘本封面`,true);
 await fs.writeFile(path.join(CACHE,`${story.id}-cover.svg`),coverSource);
 await sharp(Buffer.from(coverSource)).png({compressionLevel:9}).toFile(path.join(dir,'cover.png'));
 console.log(`${story.id}: ${pages.length} pages + cover`);
}

if(!sample){
 const note=[
  '# 原创绘本插图清单',
  '',
  '日期：2026-10-22。首版共 6 个故事、72 张正文插图、6 张封面。正文 1000 × 800，封面 1000 × 1000，PNG，全部作为离线资源打包。',
  '',
  '## 来源与制作方式',
  '',
  '所有角色造型、场景、道具、配色及 SVG 路径均为本项目原创，以程序化向量构图导出 PNG；没有使用第三方图库、抓取插画、商标角色或图像生成模型。人物、植物、建筑与叙事道具保存在可编辑绘制器中，细微噪声用于纸面质感。字体不属于插图资产：插图内不排故事正文，标题与正文由 App 的可访问文本层显示。',
  '',
  '绘制器：`scripts/render-illustrations.mjs`。中间 SVG 位于 `.cache/illustrations/`，可从脚本重建。Node.js 与 sharp 0.34.5 用于本地栅格化。固定坐标与随机种子使导出结果可重复。',
  '',
  '```sh',
  'node scripts/render-illustrations.mjs',
  'node scripts/render-illustrations.mjs --story=moon-post',
  'node scripts/render-illustrations.mjs --story=moon-post --sample',
  '```',
  '',
  '封面使用每个故事单独设计的构图，不替代任何叙事页。每页选择明确的叙事时刻；同一场景连续发生的事件保留空间关系，并变化人物姿态、道具状态或参与角色。绘制器校验分页总数，避免正文扩页后静默产生空白或重复图。',
  '',
  '## 视觉检查',
  '',
  '已逐篇检查全部 72 页的联排图，另查看 6 张封面原图。检查角色服饰连续、情节道具、无空白与重复文件，以及主角在画面中的可辨认性。月光暂时消失的段落保留遮月云；兔子具有站立、侧身蹲坐、递出荷叶与挥手姿态；鲸鱼的云丝、泡泡与降雨分别呈现；新地图成为纸帆时呈现航线与铜纽扣。未进行用户或儿童实测，画风属于首版原创向量绘本风格。',
  '',
  '## 分页与分镜对应',
 ];
 for(const story of stories){note.push('',`### ${story.title}（${story.id}）`,'',story.character,'',`封面：\`assets/stories/${story.id}/cover.png\``,'','| 文件 | 场景 | 画面中的行动 |','| --- | --- | --- |');story.pages.forEach((p,i)=>note.push(`| page-${String(i+1).padStart(2,'0')}.png | ${p.scene.setting} | ${p.scene.action} |`));}
 await fs.writeFile(path.join(ROOT,'assets/illustration-notes.md'),note.join('\n')+'\n');
}
